# GUC app.current_clinic_id is set per transaction (SET LOCAL). app.system = 'on' is the
# explicit, audited escape hatch for auth lookups, public slug resolution and background jobs.
_COND = (
    "current_setting('app.system', true) = 'on' OR "
    "{col} = nullif(current_setting('app.current_clinic_id', true), '')::uuid"
)


def _rls_and_roles() -> None:
    # Password of the runtime role comes from APP_DB_PASSWORD (the default is for local dev only).
    pw = os.environ.get("APP_DB_PASSWORD", "docly_app").replace("'", "''")
    op.execute(f"""
        DO $$ BEGIN
          IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'docly_app') THEN
            CREATE ROLE docly_app LOGIN PASSWORD '{pw}' NOSUPERUSER NOBYPASSRLS;
          ELSE
            ALTER ROLE docly_app PASSWORD '{pw}';
          END IF;
        END $$;
    """)
    op.execute("GRANT USAGE ON SCHEMA public TO docly_app")
    op.execute("GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO docly_app")
    for t in TENANT_TABLES:
        op.execute(f"ALTER TABLE {t} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {t} FORCE ROW LEVEL SECURITY")
        cond = _COND.format(col="clinic_id")
        op.execute(f"CREATE POLICY tenant_isolation ON {t} USING ({cond}) WITH CHECK ({cond})")
    op.execute("ALTER TABLE clinics ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE clinics FORCE ROW LEVEL SECURITY")
    cond = _COND.format(col="id")
    op.execute(f"CREATE POLICY tenant_isolation ON clinics USING ({cond}) WITH CHECK ({cond})")


def _drop_rls() -> None:
    for t in [*TENANT_TABLES, "clinics"]:
        op.execute(f"DROP POLICY IF EXISTS tenant_isolation ON {t}")
        op.execute(f"ALTER TABLE {t} DISABLE ROW LEVEL SECURITY")
    op.execute("REVOKE ALL ON ALL TABLES IN SCHEMA public FROM docly_app")
